 const translate = value => {
  if(typeof value!=='string') return value;
  const key=value.trim();
  if(Object.hasOwn(dictionary,key)) return value.replace(key,dictionary[key]);
  return value
   .replace(/\bShowing (\d+) of (\d+)\b/g,'Wyświetlono $1 z $2')
   .replace(/\bGroup (\d+)/g,'Grupa $1')
   .replace(/\bString (\d+)/g,'Łańcuch $1')
   .replace(/\bBattery (\d+)/g,'Akumulator $1')
   .replace(/\bTotal options: (\d+)\. Full results and exclusion reasons are available in JSON\./g,'Łącznie wariantów: $1. Pełne wyniki i przyczyny wykluczenia są dostępne w JSON.')
   .replace(/^(Less than |At least )/,(m)=>m==='Less than '?'Mniej niż ':'Co najmniej ');
 };
 window.yellowPolish=translate;
